commands.command:
set -e; AVD="$HOME/.android/avd/medium_phone.avd"; CFG="$AVD/config.ini"; test -f "$CFG"; echo BEFORE; grep -E '^(disk.dataPartition.size|hw.ramSize|fastboot.forceColdBoot|PlayStore.enabled)=' "$CFG" || true; cp "$CFG" /tmp/lcl-medium-phone-config-before-v5.ini; python3 - <<'PY'
from pathlib import Path
p=Path.home()/'.android/avd/medium_phone.avd/config.ini'
lines=p.read_text().splitlines()
updates={'disk.dataPartition.size':'2047m','hw.ramSize':'1536','fastboot.forceColdBoot':'yes'}
seen=set(); out=[]
for line in lines:
    if '=' in line:
        k=line.split('=',1)[0]
        if k in updates:
            out.append(f'{k}={updates[k]}'); seen.add(k); continue
    out.append(line)
for k,v in updates.items():
    if k not in seen: out.append(f'{k}={v}')
p.write_text('\n'.join(out)+'\n')
PY
rm -f "$AVD/userdata-qemu.img" "$AVD/userdata-qemu.img.qcow2" "$AVD/cache.img"; echo AFTER; grep -E '^(disk.dataPartition.size|hw.ramSize|fastboot.forceColdBoot|PlayStore.enabled)=' "$CFG"; du -sh "$AVD"; df -h "$HOME"
